INSERT INTO `wp_postmeta` VALUES (1609,224,'_form','<div class=\"form-commander\">\n<h2>Votre commande</h2>\n<div class=\"gouts\">\n<div class=\"card\">\n<div>\n<img src=\"http://planty.local/wp-content/uploads/2025/10/Group-12.png\" />\n</div>\n<div>\n<span>[number fraise class:fraise-input min:0 \"0\"]</span>\n</div>\n</div>\n<div class=\"card\">\n<div>\n<img src=\"http://planty.local/wp-content/uploads/2025/10/Group-13.png\" />\n</div>\n<div>\n<span>[number pamplemousse class:pamplemousse-input min:0 \"0\"]</span>\n</div>\n</div><div class=\"card\">\n<div>\n<img src=\"http://planty.local/wp-content/uploads/2025/10/framboise.png\" />\n</div>\n<div>\n<span>[number framboise class:framboise-input min:0 \"0\"]</span>\n</div>\n</div><div class=\"card\">\n<div>\n<img src=\"http://planty.local/wp-content/uploads/2025/10/citron.png\" />\n</div>\n<div>\n<span>[number citron class:citron-input min:0 \"0\"]</span>\n</div>\n</div>\n</div>\n\n<hr />\n\n<div class=\"infos-livraison\">\n\n<div class=\"infos\">\n<h2>Vos informations</h2>\n<label for=\"nom\">Nom</label>\n[text* nom]\n<label for=\"prenom\">Prénom</label>\n[text* prenom]\n<label for=\"email\">E-mail</label>\n[text* email]\n</div>\n\n<div class=\"livraison\">\n<h2>Livraison</h2>\n<label for=\"adresse\">Adresse de livraison</label>\n[text* adresse]\n<label for=\"code-postal\">Code postal</label>\n[text* code-postal]\n<label for=\"ville\">Ville</label>\n[text* ville]\n</div>\n\n\n\n</div>\n[submit \"Commander\"]\n\n</div>');
INSERT INTO `wp_postmeta` VALUES (1610,224,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:22:\"[_site_title] Commande\";s:6:\"sender\";s:38:\"[_site_title] <wordpress@planty.local>\";s:9:\"recipient\";s:23:\"planty.drinks@gmail.com\";s:4:\"body\";s:395:\"From: [prenom] [nom] [email]\nSubject: Commande\n\nMessage Body:\n\nBonjour !\n\nUne nouvelle commande !\n- fraise : [fraise]\n- pamplemousse : [pamplemousse]\n- framboise : [framboise]\n- citron : [citron]\n\net c\'est pour :\n\n[prenom] [nom]\n[adresse]\n[code-postal] [ville]\n\nAdresse e-mail : [email]\n\n\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:17:\"Reply-To: [email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}');
