INSERT INTO `wp_posts` VALUES (250,1,'2025-10-22 08:31:37','2025-10-22 06:31:37','<h2>NOUS RENCONTRER</h2>															<img width=\"191\" height=\"188\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-2.png\" alt=\"image de fleur planty\" />													<p>Chez Planty nous sommes tous passionnés par le bien-être, et ça se retrouve dans nos boissons ! Notre start-up s’est construite au fur et à mesure de rencontres entre amoureux des plantes.</p>			<h2>L’équipe</h2>															<img width=\"167\" height=\"167\" src=\"http://planty.local/wp-content/uploads/2025/10/Megan.png\" alt=\"Image de Megane\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Megan.png 167w, http://planty.local/wp-content/uploads/2025/10/Megan-150x150.png 150w\" sizes=\"(max-width: 167px) 100vw, 167px\" />																										<img width=\"167\" height=\"167\" src=\"http://planty.local/wp-content/uploads/2025/10/Brooke.png\" alt=\"Image de Brooke\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Brooke.png 167w, http://planty.local/wp-content/uploads/2025/10/Brooke-150x150.png 150w\" sizes=\"(max-width: 167px) 100vw, 167px\" />																										<img width=\"167\" height=\"167\" src=\"http://planty.local/wp-content/uploads/2025/10/Sylvie.png\" alt=\"Image de Sylvie\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Sylvie.png 167w, http://planty.local/wp-content/uploads/2025/10/Sylvie-150x150.png 150w\" sizes=\"(max-width: 167px) 100vw, 167px\" />																<h2>Mégane</h2>					<h2>Brooke</h2>					<h2>Sylvie</h2>		<p>CEO</p><p>Nutritionniste</p><p>Mixologue</p>													<img width=\"262\" height=\"300\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-4-262x300.png\" alt=\"Image de la plante\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Group-4-262x300.png 262w, http://planty.local/wp-content/uploads/2025/10/Group-4.png 350w\" sizes=\"(max-width: 262px) 100vw, 262px\" />																		\n							<h2>Nous contacter</h2>							\n				[contact-form-7 id=\"46bb219\" title=\"Contact form 1\"]													<img width=\"185\" height=\"178\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-16.png\" alt=\"\" />																										<img width=\"1024\" height=\"93\" src=\"http://planty.local/wp-content/uploads/2025/10/bordenbas-1024x93.png\" alt=\"Images des canettes de planty\" srcset=\"http://planty.local/wp-content/uploads/2025/10/bordenbas-1024x93.png 1024w, http://planty.local/wp-content/uploads/2025/10/bordenbas-300x27.png 300w, http://planty.local/wp-content/uploads/2025/10/bordenbas-768x70.png 768w, http://planty.local/wp-content/uploads/2025/10/bordenbas.png 1438w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />','Précommande','','inherit','closed','closed','','62-revision-v1','','','2025-10-22 08:31:37','2025-10-22 06:31:37','',62,'http://planty.local/?p=250',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (251,1,'2025-10-30 14:15:45','2025-10-30 13:15:45','<h2>BOISSON ÉNERGISANTE<br>100% NATURELLE</h2>															<img width=\"1024\" height=\"745\" src=\"http://planty.local/wp-content/uploads/2025/10/canette-1024x745.png\" alt=\"canette planty\" srcset=\"http://planty.local/wp-content/uploads/2025/10/canette-1024x745.png 1024w, http://planty.local/wp-content/uploads/2025/10/canette-300x218.png 300w, http://planty.local/wp-content/uploads/2025/10/canette-768x559.png 768w, http://planty.local/wp-content/uploads/2025/10/canette-1536x1117.png 1536w, http://planty.local/wp-content/uploads/2025/10/canette-2048x1490.png 2048w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																										<img width=\"262\" height=\"300\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-4-262x300.png\" alt=\"Image de la plante\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Group-4-262x300.png 262w, http://planty.local/wp-content/uploads/2025/10/Group-4.png 350w\" sizes=\"(max-width: 262px) 100vw, 262px\" />																										<img width=\"262\" height=\"300\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-3-262x300.png\" alt=\"\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Group-3-262x300.png 262w, http://planty.local/wp-content/uploads/2025/10/Group-3.png 350w\" sizes=\"(max-width: 262px) 100vw, 262px\" />																<h2>L’énergie des plantes</h2>		<p> Planty, c’est la première boisson<br />énergisante composée à 100 % de produits naturels. <br />Avec son goût frais et fruité, retrouvez votre <br />énergie grâce aux plantes riches en vitamine B2, <br />à n’importe quel moment de la journée.</p>			<h2>LES GOûTS</h2>		<p>Nous avons une saveur pour chaque moment de votre journée.</p>													<img width=\"393\" height=\"262\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-12.png\" alt=\"fraise\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Group-12.png 393w, http://planty.local/wp-content/uploads/2025/10/Group-12-300x200.png 300w\" sizes=\"(max-width: 393px) 100vw, 393px\" />																										<img width=\"394\" height=\"263\" src=\"http://planty.local/wp-content/uploads/2025/10/Group-13.png\" alt=\"pamplemousse\" srcset=\"http://planty.local/wp-content/uploads/2025/10/Group-13.png 394w, http://planty.local/wp-content/uploads/2025/10/Group-13-300x200.png 300w\" sizes=\"(max-width: 394px) 100vw, 394px\" />																										<img width=\"393\" height=\"262\" src=\"http://planty.local/wp-content/uploads/2025/10/framboise.png\" alt=\"Image de framboise\" srcset=\"http://planty.local/wp-content/uploads/2025/10/framboise.png 393w, http://planty.local/wp-content/uploads/2025/10/framboise-300x200.png 300w\" sizes=\"(max-width: 393px) 100vw, 393px\" />																										<img width=\"393\" height=\"262\" src=\"http://planty.local/wp-content/uploads/2025/10/citron.png\" alt=\"Image d&#039;un citron\" srcset=\"http://planty.local/wp-content/uploads/2025/10/citron.png 393w, http://planty.local/wp-content/uploads/2025/10/citron-300x200.png 300w\" sizes=\"(max-width: 393px) 100vw, 393px\" />																					<a href=\"http://planty.local/precommande/\">\n									Commander\n					</a>\n									<h2>CE QU’ILS EN PENSENT</h2>															<img width=\"127\" height=\"139\" src=\"http://planty.local/wp-content/uploads/2025/10/p1.png\" alt=\"p1\" />																<h2>Fatiha</h2>		<p>La meilleure boisson énergisante disponible sur le marché !</p>													<img width=\"127\" height=\"139\" src=\"http://planty.local/wp-content/uploads/2025/10/p2.png\" alt=\"\" />																<h2>Véro</h2>		<p>Frais &amp; fruité c’est parfait pour accompagner le goûter.</p>													<img width=\"127\" height=\"139\" src=\"http://planty.local/wp-content/uploads/2025/10/p3.png\" alt=\"\" />																<h2>Marc</h2>		<p>Un boost d’énergie sans produits chimiques, un vrai plus dans ma journée.</p>													<img width=\"1024\" height=\"93\" src=\"http://planty.local/wp-content/uploads/2025/10/bordenbas-1024x93.png\" alt=\"Images des canettes de planty\" srcset=\"http://planty.local/wp-content/uploads/2025/10/bordenbas-1024x93.png 1024w, http://planty.local/wp-content/uploads/2025/10/bordenbas-300x27.png 300w, http://planty.local/wp-content/uploads/2025/10/bordenbas-768x70.png 768w, http://planty.local/wp-content/uploads/2025/10/bordenbas.png 1438w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />','page d\'accueil','','inherit','closed','closed','','2-autosave-v1','','','2025-10-30 14:17:41','2025-10-30 13:17:41','',2,'http://planty.local/?p=251',0,'revision','',0);
